import { z } from 'zod';
import { paginationQuery } from '../../utils/http';

/** Clinical free text. Always typed by the doctor — never generated by the application. */
const clinicalText = (max: number) => z.string().trim().max(max).nullable().optional();

export const updateConsultationSchema = z.object({
  chiefComplaint: clinicalText(1000),
  notes: clinicalText(4000),
  diagnosis: clinicalText(1000),
  observations: clinicalText(2000),
  followUpDate: z.iso.date('Use the format YYYY-MM-DD.').nullable().optional(),
});

export const listConsultationsQuery = paginationQuery.extend({
  scope: z.enum(['active', 'completed', 'all']).default('all'),
  patientId: z.uuid().optional(),
});

export type UpdateConsultationInput = z.infer<typeof updateConsultationSchema>;
export type ListConsultationsQuery = z.infer<typeof listConsultationsQuery>;
